  if(!allowed.includes(parts[0].replace('.html','')))return fallback;const keys={customer:['id','action'],'customer-allocations':['id'],receipt:['id','print'],'purchase-receipt':['id','print'],statement:['id'],supplier:['id','action'],'supplier-statement':['id'],stock:['product','mode','limit','q'],cash:['kind'],customers:['debt','repay'],suppliers:['debt','payable','pay'],labels:['kind'],products:['new'],waste:['product','id'],'stock-adjustment':['product','id'],'owner-cash':['member','from','to'],'daily-close':['day']};
